// Chartolj! — English lesson translations, module 3 (Risk Management).
// Keys are LESSONS_DATA indices; quiz option order matches LESSONS_DATA.
window.LESSONS_EN = Object.assign(window.LESSONS_EN || {}, {
"17": {"t": "Position Sizing", "s": "How much should you risk on a single trade?", "cards": [
  {"t": "The 1–2% rule", "b": "<p>Most experienced traders recommend <strong style=\"color:#FF3D5A\">never risking more than 1–2% of your total capital on a single trade</strong>. This means that even a series of losing trades won't put you in danger.</p>"},
  {"t": "How do you calculate position size?", "b": "<p>The formula: <strong style=\"color:#FF3D5A\">(Capital × Risk%) ÷ (Entry price − Stop-loss price)</strong> = the number of units you can buy. This ensures that if the stop-loss is hit you lose exactly the planned amount, not more.</p>"},
  {"t": "Why shouldn't you size \"by feel\"?", "b": "<p>If you size a position only on gut feeling, excitement or confidence, you can easily take <strong style=\"color:#FF3D5A\">too big a stake</strong> on a trade that \"looks certain\" — yet nothing in the market is guaranteed, and it is exactly these \"certain\" trades that cause the biggest losses when they go wrong.</p>"},
  {"t": "Protecting capital is the primary goal", "b": "<p>The most important rule of day trading is not maximising profit but <strong style=\"color:#FF3D5A\">protecting capital</strong> — if you lose your capital, you can't keep trading. Consistent, low-risk position sizing matters more in the long run than the outcome of any single trade.</p>"}],
 "qs": [
  {"q": "What is the main purpose of position sizing?", "o": ["Opening the largest possible position", "Maximising the number of positions", "Maximising leverage", "Controlling the risk on every single trade"], "e": "The purpose of position sizing is to consciously control the risk on every single trade."},
  {"q": "What is the essence of the 1% rule?", "o": ["No single trade should risk more than 1% of capital", "Position size is always exactly 1% of capital, regardless of anything", "Daily profit is always automatically capped at exactly 1%", "The broker's commission is always 1% of capital, without exception"], "e": "According to the 1% rule, no single trade should risk more than 1% of total capital."},
  {"q": "Why does the stop-loss distance matter for sizing?", "o": ["It does not matter, position size never depends on the stop distance", "It determines how many units we can buy with the given risk amount", "Because sizing is always independent of risk management rules", "Because the stop distance only affects the size of the profit"], "e": "The stop-loss distance determines how many units we can buy with the allowed risk amount."},
  {"q": "What happens with too large a position size?", "o": ["Nothing negative, it always improves the final result", "It automatically reduces risk in every single case", "The broker automatically limits it, always without risk", "A single bad trade can cause disproportionately large damage"], "e": "With too large a position size, a single bad trade can cause disproportionately large damage to capital."},
  {"q": "Why is it worth sizing as a % of capital rather than a fixed amount?", "o": ["It automatically adapts to capital growing or shrinking", "Because a fixed amount always gives a more accurate result", "It isn't worth it, a fixed amount is always simpler and better", "Because the law requires exclusive use of percentage calculation"], "e": "Percentage-based sizing automatically adapts to capital actually growing or shrinking."}]},
"18": {"t": "Stop-Loss and Take-Profit Strategies", "s": "How to close a position — by plan, not emotion", "cards": [
  {"t": "Why is a stop-loss mandatory on every position?", "b": "<p>A <strong style=\"color:#FF3D5A\">stop-loss</strong> is a predefined price level where you automatically close a losing position. Without it, a single bad trade could theoretically lead to unlimited loss — the stop-loss is the most important safety net in day trading.</p>"},
  {"t": "Where should you put the stop-loss?", "b": "<p>It is worth aligning the stop-loss with <strong style=\"color:#FF3D5A\">technical levels</strong> (e.g. below a nearby support for a long position), not just an arbitrary dollar amount — so the market's \"normal noise\" doesn't knock you out of an otherwise good position prematurely.</p>"},
  {"t": "The role of the take-profit", "b": "<p>A <strong style=\"color:#FF3D5A\">take-profit</strong> defines in advance where you close a profitable position — this protects you from holding the position too long out of greed, with the profit eventually giving itself back on a reversal.</p>"},
  {"t": "Why shouldn't you move the stop-loss in the direction of the loss?", "b": "<p>One of the most common beginner mistakes is, as the position approaches the stop, <strong style=\"color:#FF3D5A\">\"hopefully\" pushing the stop further away</strong> to \"give the trade another chance\". This is exactly the opposite of disciplined risk management and typically leads to a bigger loss.</p>"}],
 "qs": [
  {"q": "What is the main function of a stop-loss?", "o": ["Automatic exit at a predefined loss level", "Automatically increasing the position on a loss", "Always maximising profit on every single trade", "Automatically doubling the profit"], "e": "The main function of a stop-loss is an automatic exit at a predefined loss level."},
  {"q": "What is the main function of a take-profit?", "o": ["Automatically and deliberately ignoring the daily limit", "Always automatically limiting the loss at a given level", "Automatic exit at a predefined profit target", "Continuously and automatically increasing position size when in profit"], "e": "A take-profit provides an automatic exit at a predefined profit target."},
  {"q": "Why shouldn't you put the stop at an obvious, round level?", "o": ["It does not matter, the stop can go anywhere in every case", "Many traders put it in the same place, creating a concentration", "Because the stop's location never affects risk in any case", "Because round levels are always the safest stop locations"], "e": "Many traders place their stop at obvious, round levels, which can create a concentration."},
  {"q": "Why shouldn't you change the stop too often on an emotional basis?", "o": ["Because changing the stop never affects the end result at all", "Emotion-based changes can override the rational plan", "You should, it is always worth changing the stop often by feel", "Because the broker automatically restores the original stop level"], "e": "Emotion-based stop changes can override the risk management planned rationally in advance."},
  {"q": "What is the essence of a trailing stop?", "o": ["Automatically and immediately deleting the take-profit level in every case", "The stop moves with the price, protecting the accumulated profit", "A fixed, unchanging stop level that can never be modified", "The stop is always deleted automatically when the position is profitable"], "e": "A trailing stop moves with the price, thereby protecting part of the profit already accumulated."}]},
"19": {"t": "The Risk/Reward Ratio", "s": "Why you can win even if you lose more often than you win", "cards": [
  {"t": "What is the Risk/Reward ratio?", "b": "<p>The <strong style=\"color:#FF3D5A\">Risk/Reward ratio</strong> measures how large a potential profit you are targeting relative to the risk taken. If you risk $100 and target a $300 profit, that is a 1:3 ratio.</p>"},
  {"t": "Why don't you need to win every trade?", "b": "<p>With a <strong style=\"color:#FF3D5A\">1:3 risk/reward ratio</strong> you are profitable in the long run even if you win only 30–40% of your trades — because the winning trades are much larger than the losing ones.</p>"},
  {"t": "The relationship between win rate and risk/reward", "b": "<p>The two measures <strong style=\"color:#FF3D5A\">together determine long-term profitability</strong> — a high win rate with a low risk/reward can be just as unprofitable overall as a low win rate with an excellent risk/reward can be profitable.</p>"},
  {"t": "Why do experienced traders avoid ratios below 1:1?", "b": "<p>If your potential loss is bigger than your potential profit (e.g. a 1:0.5 ratio), <strong style=\"color:#FF3D5A\">you need an extremely high win rate</strong> to be profitable — an unrealistic expectation for most trading styles, which is why experienced traders typically aim for at least 1:1.5 or 1:2.</p>"}],
 "qs": [
  {"q": "What is the Risk/Reward ratio?", "o": ["The relationship between potential risk and potential return on a trade", "The simple aggregated difference between daily profit and loss", "The simple ratio of the market's daily opening and closing prices", "The exact quotient of the broker's commission and the stake size"], "e": "The Risk/Reward ratio shows the relationship between potential risk and potential return on a given trade."},
  {"q": "What does a 1:3 ratio mean?", "o": ["The risk is always three times the possible return", "The position size automatically triples on entry", "The possible return is three times the risk taken", "The win rate is exactly 3%, nothing else follows from it"], "e": "A 1:3 ratio means the possible return is three times the risk taken."},
  {"q": "Why does it matter when viewed together with the win rate?", "o": ["A good ratio can be profitable even with a lower win rate", "It doesn't matter, the ratio alone is always enough", "Because the win rate never affects the end result at all", "Because only the win rate counts, the ratio is completely irrelevant"], "e": "A good Risk/Reward ratio can be profitable in the long run even with a lower win rate."},
  {"q": "How do you calculate it in practice?", "o": ["As the product of daily volume and spread width", "By dividing the distances of the target and the stop-loss from the entry", "As the quotient of the market's opening hours and the daily limit", "As the simple quotient of the entry price and the broker's commission"], "e": "The Risk/Reward ratio is calculated by dividing the distances of the target price and the stop-loss from the entry."},
  {"q": "Why shouldn't you decide on a trade based on the ratio alone?", "o": ["Because the ratio is never relevant to any decision", "Because the ratio always overrides the result of technical analysis", "Its probability must also be considered, not just the ratio", "Because you must always choose only the trade with the highest ratio"], "e": "Besides the bare ratio, the setup's probability must also be considered in the decision."}]},
"20": {"t": "The Daily Loss Limit", "s": "The rule that protects you from a catastrophic day", "cards": [
  {"t": "What is a daily loss limit?", "b": "<p>A <strong style=\"color:#FF3D5A\">daily loss limit</strong> is a predefined amount or percentage (e.g. 3% of capital), on reaching which <strong style=\"color:#FF3D5A\">you must stop trading for the day</strong>, regardless of how much you would like to \"win it back\".</p>"},
  {"t": "Why isn't a single position's stop-loss enough?", "b": "<p>A single position's stop-loss protects you on that trade, but <strong style=\"color:#FF3D5A\">doesn't protect you</strong> from making several losing trades in a row on a bad day — the daily limit protects against this aggregated risk.</p>"},
  {"t": "Recognising and accepting a \"bad day\"", "b": "<p>Every trader has bad days — when reading the market simply doesn't work. The daily limit helps you <strong style=\"color:#FF3D5A\">objectively recognise and accept</strong> this, instead of trying to force a turnaround emotionally with ever bigger stakes.</p>"},
  {"t": "What happens if you reach the limit?", "b": "<p>If you reach the daily loss limit, the best thing you can do is <strong style=\"color:#FF3D5A\">close the platform and not trade until tomorrow</strong>. This isn't weakness — it is exactly the discipline that distinguishes successful traders from those who fail in the long run.</p>"}],
 "qs": [
  {"q": "What is the essence of the daily loss limit?", "o": ["A predefined maximum loss after which we stop", "A daily profit target after which we stop", "A monthly tally of losses after the fact", "A daily profit target that must be reached no matter what"], "e": "The daily loss limit is a predefined maximum loss, on reaching which we stop for the day."},
  {"q": "Why is this important in defending against tilt?", "o": ["It does not matter, tilt never relates to the daily limit", "Because the limit is only relevant on profitable days", "It prevents a bad day from becoming catastrophic", "Because tilt always disappears automatically once the limit is set"], "e": "The daily limit prevents a bad day's loss from becoming catastrophic under emotional influence."},
  {"q": "What typical size do many use for the limit?", "o": ["Always exactly 100% of total capital, without risk", "There is no typical size, it must always be chosen at random", "50% of total capital, which counts as an extremely high threshold", "A few percent of capital, e.g. 2–3%"], "e": "Many use a few percent of capital, e.g. 2–3%, as their daily loss limit."},
  {"q": "What happens if someone ignores their own limit?", "o": ["The final daily result automatically improves in every case", "The broker always automatically stops trading for them", "They risk increasing the loss further under the influence of tilt", "Nothing negative, ignoring the limit is always safe"], "e": "Ignoring the limit risks the daily loss growing further under the influence of tilt."},
  {"q": "Why must the limit be 'non-negotiable'?", "o": ["Because non-negotiable rules always worsen the result", "The temptation to continue is strongest precisely on a losing day", "It needn't be, it can always be overridden when you feel good", "Because the limit never affects actual trading behaviour"], "e": "The limit must be non-negotiable because precisely on a bad day the temptation to continue is strongest."}]},
"35": {"t": "Kelly Criterion Basics", "s": "The mathematical formula for the optimal stake size", "cards": [
  {"t": "What is the Kelly Criterion?", "b": "<p>The <strong style=\"color:#FF3D5A\">Kelly Criterion</strong> is a mathematical formula that, based on your win rate and your average win/loss ratio, calculates what fraction of capital you should theoretically risk on a trade to maximise long-term growth.</p>"},
  {"t": "Why do many only use 'half Kelly'?", "b": "<p>The stake size suggested by pure Kelly is often <strong style=\"color:#FF3D5A\">extremely aggressive and volatile</strong> — so many experienced traders only apply half of the Kelly formula (\"half Kelly\"), significantly reducing risk at the cost of a small loss of return.</p>"},
  {"t": "Why is it hard to apply precisely in live trading?", "b": "<p>The Kelly formula <strong style=\"color:#FF3D5A\">needs a precise win rate and win/loss ratio</strong> — in reality these are never known for sure in advance, only estimated from past data, which makes practical application uncertain.</p>"},
  {"t": "Why is it still important to know the principle?", "b": "<p>Even if you don't calculate it precisely on every trade, the Kelly Criterion <strong style=\"color:#FF3D5A\">teaches the principle</strong> that stake size must match your win rate and risk/reward ratio — it can't be a fixed, arbitrary number.</p>"}],
 "qs": [
  {"q": "What is the purpose of the Kelly Criterion?", "o": ["Precisely determining the market's official opening hours", "Setting an official, mandatory upper limit on the number of daily trades", "Precisely calculating the broker's monthly commission in forints", "Determining the optimal stake size for long-term growth"], "e": "The Kelly Criterion is a mathematical formula that determines the optimal stake size for long-term capital growth."},
  {"q": "What data does the formula need?", "o": ["Only the market's official opening time, no other data is needed", "Only the average daily volume, no other data is needed", "Only the exact size of the broker's commission in forints", "The win rate and the average win/loss ratio"], "e": "The Kelly formula needs the win rate and the average win/loss ratio as inputs."},
  {"q": "Why is using the full Kelly stake risky?", "o": ["Because the Kelly Criterion can never be used in real trading", "Because full Kelly always suggests too low, too cautious a stake", "It can cause extremely high volatility in the short term", "It isn't risky, it always gives a safe and stable stake size"], "e": "The full Kelly stake is mathematically optimal but can cause extremely high volatility in the short term."},
  {"q": "What is the 'half Kelly' approach?", "o": ["Precisely doubling the Kelly stake in every case", "Using half of the calculated Kelly stake, a more conservative approach", "Changing the stake size randomly every day, without risk", "Completely and permanently rejecting and ignoring the Kelly formula"], "e": "Half Kelly uses half of the calculated stake, reducing volatility in exchange for part of the growth rate."},
  {"q": "Why are accurate inputs important for the Kelly formula?", "o": ["Because the formula always automatically corrects inaccurate input", "Inaccurate data can produce a wrong, even overly aggressive stake size", "Because the Kelly formula is never sensitive to input accuracy", "It does not matter, any estimated data can be equally good"], "e": "Inaccurate inputs (win rate, R:R) can produce a wrong, even overly aggressive stake size."}]},
"36": {"t": "Correlation Risk Across Multiple Positions", "s": "When your 'diversified' portfolio actually moves in one direction", "cards": [
  {"t": "What is correlation risk?", "b": "<p><strong style=\"color:#FF3D5A\">Correlation risk</strong> appears when several SEEMINGLY different positions actually move similarly in response to a given market event — so the \"diversification\" is an illusion, and your real risk is much bigger than you think.</p>"},
  {"t": "An example of hidden correlation", "b": "<p>If you hold Long positions in <strong style=\"color:#FF3D5A\">several tech stocks AND Bitcoin</strong> at the same time, these often correlate strongly during a general risk-off mood — they can fall together, even if they seem to be \"different asset classes\".</p>"},
  {"t": "Why does correlation rise precisely during a crisis?", "b": "<p>In calm markets correlation between assets can be lower, but <strong style=\"color:#FF3D5A\">in sharp market stress correlations tend to jump suddenly</strong> — everyone flees risky assets at once, regardless of their individual characteristics.</p>"},
  {"t": "How do you handle this as a day trader?", "b": "<p>It is worth <strong style=\"color:#FF3D5A\">thinking in terms of aggregate exposure, not just individual positions</strong> — if your 3 positions all correlate strongly, your real risk is closer to that of a single position 3x bigger than to three independent risks.</p>"}],
 "qs": [
  {"q": "What is correlation risk?", "o": ["The risk of several seemingly independent positions moving together", "Calculating position size with the Kelly Criterion", "The standalone risk of a single position", "The maximum cap on the number of daily trades"], "e": "Correlation risk appears when several positions actually react similarly to a market event."},
  {"q": "Why can there be hidden correlation between Bitcoin and tech stocks?", "o": ["They can fall together during a risk-off mood", "There is never any relationship between them", "Bitcoin never correlates with anything", "They always move in opposite directions"], "e": "Bitcoin and tech stocks often fall together during a general risk-off market mood."},
  {"q": "Why does correlation rise during a crisis?", "o": ["It doesn't rise, it always falls in a crisis", "Everyone flees risky assets at the same time", "It is just a formal phenomenon", "It only happens in theory"], "e": "In a crisis correlations jump, because investors flee risk en masse."},
  {"q": "How do you handle this as a day trader?", "o": ["By ignoring it", "By only thinking position by position", "By thinking in terms of aggregate exposure", "With maximum stakes on every position"], "e": "Thinking in terms of aggregate exposure helps assess the real, correlated risk."},
  {"q": "What happens with 3 strongly correlated positions?", "o": ["The real risk is close to that of a 3x bigger position", "Risk automatically falls", "The risk is divided exactly by three", "There is no extra risk"], "e": "With strongly correlated positions the real risk is closer to that of a much bigger, single position."}]},
"37": {"t": "The Concept of Maximum Drawdown", "s": "The biggest fall from the peak your account has ever suffered", "cards": [
  {"t": "What is maximum drawdown?", "b": "<p><strong style=\"color:#FF3D5A\">Maximum drawdown</strong> is the biggest percentage fall your trading account has ever suffered from its highest (peak) value to the following low.</p>"},
  {"t": "Why is it a more important measure than bare return?", "b": "<p>Two traders can achieve the same annual return, but if one had a <strong style=\"color:#FF3D5A\">50% maximum drawdown and the other only 15%</strong>, the latter's strategy is far more sustainable and psychologically easier to endure.</p>"},
  {"t": "The mathematical trap of drawdown", "b": "<p>It is important to understand: after a <strong style=\"color:#FF3D5A\">50% loss you need a 100% return</strong> just to get back to the starting level — the bigger the drawdown, the disproportionately bigger the return needed to recover.</p>"},
  {"t": "How can you reduce the risk of maximum drawdown?", "b": "<p>Strict <strong style=\"color:#FF3D5A\">position sizing, a daily loss limit and avoiding correlated positions</strong> all reduce the chance that a single bad period causes a catastrophic drawdown.</p>"}],
 "qs": [
  {"q": "What is Maximum Drawdown?", "o": ["The broker's total monthly commission expressed in forints", "The biggest peak-to-trough decline of capital", "The simple aggregated amount of average daily profit", "The simple difference between the market's daily opening and closing prices"], "e": "Maximum Drawdown measures capital's biggest decline from peak to trough."},
  {"q": "Why is this sometimes more important than bare profit?", "o": ["Because drawdown is always higher than actual profit", "It isn't more important, only the final profit ever counts", "Because drawdown never relates to the quality of a strategy", "It shows how big a psychological/financial burden had to be endured"], "e": "Drawdown shows how big a psychological and financial burden had to be endured along the way."},
  {"q": "What is the relationship between drawdown size and the return needed to recover?", "o": ["There is actually never any relationship between the two", "Non-linear: an ever bigger return is needed for a bigger drawdown", "Always a linear, directly proportional relationship", "The same return is always enough to recover"], "e": "The relationship is non-linear: the bigger the drawdown, the proportionally bigger the return needed to recover."},
  {"q": "Why is it important to consider this in stake sizing?", "o": ["Because drawdown is always automatically limited and stays small", "Overly aggressive sizing can cause extreme drawdown", "Because stake sizing never affects the size of drawdown", "It does not matter, stake sizing is completely independent of it"], "e": "Overly aggressive position sizing can cause an extreme drawdown that is hard to recover from."},
  {"q": "What is worth doing after a significant drawdown?", "o": ["Continuing with exactly the same size as before", "Reducing stake size until stability returns", "Immediately and significantly increasing stake size to win it back", "Giving up trading immediately and permanently, completely"], "e": "After a significant drawdown it is worth reducing stake size until stability returns."}]},
"51": {"t": "The Trailing Stop-Loss Strategy", "s": "The stop that moves along with the profit", "cards": [
  {"t": "What is a trailing stop-loss?", "b": "<p>A <strong style=\"color:#FF3D5A\">trailing stop</strong> is a dynamic stop-loss that, as the position's profit grows, automatically \"follows\" the price at a predefined distance, but never moves back in the original direction.</p>"},
  {"t": "How does it protect accumulated profit?", "b": "<p>As the price <strong style=\"color:#FF3D5A\">moves in your favour, the trailing stop moves after it</strong>, locking in an ever larger share of the profit already gained — so even on a sudden reversal you don't lose the whole profit.</p>"},
  {"t": "What distance should you choose?", "b": "<p>It is often worth setting the trailing stop distance <strong style=\"color:#FF3D5A\">based on ATR (volatility)</strong> — too tight a stop can knock you out of a good position prematurely on normal market noise, too wide can let too much profit be given back.</p>"},
  {"t": "Why isn't it a perfect solution in every situation?", "b": "<p>A trailing stop is <strong style=\"color:#FF3D5A\">excellent on a strong, steady trend day</strong>, but in a choppy, sideways market it can easily knock you out of a position prematurely due to normal fluctuation, before the trend actually continues.</p>"}],
 "qs": [
  {"q": "What is the essence of a trailing stop-loss?", "o": ["The stop stays at a fixed level until the end of the position", "The stop is automatically deleted as soon as the position becomes profitable", "A fixed, unchanging stop level that can never be modified in any way", "The stop follows the price in the favourable direction, preserving part of the profit"], "e": "A trailing stop moves with the price in the favourable direction, thereby protecting part of the profit already accumulated."},
  {"q": "Why doesn't the trailing stop move back in the unfavourable direction?", "o": ["Because the broker resets it manually every day at midnight", "It does move back, it always follows the price symmetrically in both directions", "It can only move in one direction, protecting the profit achieved earlier", "Because the trailing stop never works in practice in any case"], "e": "A trailing stop can only move in the favourable direction, never backwards, protecting the profit achieved."},
  {"q": "On what basis can the trailing stop distance be set?", "o": ["Only at a fixed value predefined by the broker", "Only based on daily volume, ignoring other factors", "Only at a fixed, dollar-based distance, no other method exists", "On an ATR basis, a percentage basis or at technical levels"], "e": "The trailing stop distance can be set on an ATR basis, a percentage basis or at technical levels."},
  {"q": "What is the drawback of too tight a trailing stop?", "o": ["It never affects the trade's end result in any way", "It always maximises the possible profit in every case", "It has no drawback, it is always the best, safest solution", "It can cause an early exit on a normal, healthy pullback"], "e": "Too tight a trailing stop can cause an early exit even on an otherwise normal, healthy market pullback."},
  {"q": "When is using a trailing stop especially useful?", "o": ["In a strong, lasting trend, to protect part of the profit", "Only on losing positions, never needed on profitable ones", "Only in a sideways, directionless market, needless in other situations", "Never useful, it is always better to use a fixed take-profit instead"], "e": "A trailing stop is especially useful in a strong, lasting trend, to protect part of the accumulated profit."}]},
"52": {"t": "Diversification in Day Trading", "s": "Why it differs from long-term investing", "cards": [
  {"t": "What is diversification in the traditional sense?", "b": "<p>Traditional <strong style=\"color:#FF3D5A\">diversification</strong> means investing capital in many different assets, reducing individual risk — a well-proven principle in long-term investing.</p>"},
  {"t": "Why is the situation different in day trading?", "b": "<p>In day trading <strong style=\"color:#FF3D5A\">focus and attention are limited resources</strong> — if you try to watch too many assets/positions at once, the quality of decision-making drops on every position.</p>"},
  {"t": "The principle of \"concentrated expertise\"", "b": "<p>Many successful day traders prefer to <strong style=\"color:#FF3D5A\">specialise in a narrower set of instruments</strong>, getting to know their particular behaviour deeply (volatility patterns, typical times of day), rather than trying to trade many superficially known instruments.</p>"},
  {"t": "So where does diversification belong in day trading?", "b": "<p>In a day trading context diversification appears more in <strong style=\"color:#FF3D5A\">risk management (position sizing, avoiding correlation risk)</strong>, not in the principle of \"watching many instruments at once\".</p>"}],
 "qs": [
  {"q": "What is the basic principle of diversification in day trading?", "o": ["Investing all capital in a single, well-chosen instrument", "Spreading risk across several different instruments", "An official, mandatory upper limit on the number of daily trades", "Putting all capital into a single instrument for maximum profit"], "e": "The basic principle of diversification is spreading risk across several different instruments, not concentrating it in a single position."},
  {"q": "Why isn't choosing more instruments enough for diversification?", "o": ["If the instruments correlate strongly, real diversification is missing", "It is enough, it is always the only, complete criterion for diversification", "Because every instrument always automatically moves independently of the others", "Because correlation never affects how effective diversification is"], "e": "If the chosen instruments correlate strongly with each other, the effect of real diversification is missing or weak."},
  {"q": "Why is real diversification harder in day trading than in the long term?", "o": ["Because the broker always limits the number of positions open at once", "There is less time to follow many thoroughly analysed instruments at once", "Because day trading rules out any possibility of diversification", "It isn't harder, it is exactly as easy in both cases"], "e": "Because of day trading's fast pace there is less time for quality tracking of many thoroughly analysed instruments at once."},
  {"q": "Why is focus sometimes more important than spreading out?", "o": ["It isn't more important, you must always trade as many instruments as possible", "Deeper expertise can be built on fewer, well-known instruments", "Because focus always reduces the effectiveness of risk management", "Because the more instruments we watch, the better decisions we always make"], "e": "By concentrating on fewer, thoroughly known instruments, deeper expertise and better decision-making can be built."},
  {"q": "What balance is worth seeking on this question?", "o": ["Concentrating exclusively on a single instrument, always ignoring others completely", "A balance among a few well-known, low-correlation instruments", "Switching instruments randomly every day, without a plan", "Trading as many instruments as possible at once, without limits"], "e": "It is worth seeking a balance among a few well-known, low-correlation instruments, not extremes."}]},
"53": {"t": "Market-Wide Circuit Breakers", "s": "When the whole exchange halts, not just one stock", "cards": [
  {"t": "What is a market-wide circuit breaker?", "b": "<p>A <strong style=\"color:#FF3D5A\">market-wide circuit breaker</strong> is a mechanism that halts ALL exchange trading if a major index (e.g. the S&P 500) falls by a set amount (e.g. 7%, 13%, 20%) in a day.</p>"},
  {"t": "Why was this mechanism introduced?", "b": "<p>The purpose of the circuit breaker is to <strong style=\"color:#FF3D5A\">give the market time to \"calm down\"</strong> during extreme panic, preventing self-reinforcing, panicky selling waves that could even lead to a systemic crash.</p>"},
  {"t": "Which levels come with different halts?", "b": "<p>Typically there are <strong style=\"color:#FF3D5A\">several levels</strong>: for a smaller fall (e.g. 7%) a short, few-minute pause, for a bigger one (13%) a longer one, and for the most extreme (20%) trading halts for the rest of the day.</p>"},
  {"t": "Why is it important to know this as a day trader?", "b": "<p>If a market-wide circuit breaker triggers, <strong style=\"color:#FF3D5A\">all your open positions \"freeze\"</strong> for the duration of the halt — in extreme situations this can mean significant, unplannable risk.</p>"}],
 "qs": [
  {"q": "What is a market-wide circuit breaker?", "o": ["The broker's weekend maintenance period", "A kind of exchange holiday, announced in advance", "Halting a single stock", "Halting all exchange trading on a big fall"], "e": "A market-wide circuit breaker halts all exchange trading when a major index falls sharply."},
  {"q": "Why was it introduced?", "o": ["So the broker can collect more commission", "To increase volatility", "To give the market time to calm down", "It has no real purpose"], "e": "The purpose of the circuit breaker is to give the market time to calm down during extreme panic."},
  {"q": "What characterises the different levels?", "o": ["Every level is equally long", "They never actually trigger", "Only one level exists", "A longer halt for a bigger fall"], "e": "A bigger fall brings a longer halt; at the most extreme level trading stops for the rest of the day."},
  {"q": "What happens to your open positions during a market-wide halt?", "o": ["All positions freeze for the duration of the halt", "The broker closes them automatically", "Position sizes shrink automatically", "They automatically turn profitable"], "e": "During the halt all open positions freeze; no instrument can be traded."},
  {"q": "Why is this an extra risk as a day trader?", "o": ["It isn't, it is always safe", "Because commissions go up while trading is halted", "You can't react while the market risk persists", "Because a special halt surcharge is billed to the account"], "e": "During the halt you can't react to your open position, while the underlying risk persists."}]},
"67": {"t": "Expectancy — Your Strategy's Expected Value", "s": "The one number that really tells you whether your strategy is worth it", "cards": [
  {"t": "What is expectancy (expected value)?", "b": "<p><strong style=\"color:#FF3D5A\">Expectancy</strong> is a formula that tells you how much you win (or lose) on average per trade, taking into account your win rate AND the average size of wins/losses.</p>"},
  {"t": "The simplified formula", "b": "<p>Expectancy = (Win rate × Average win) − <strong style=\"color:#FF3D5A\">((1 − Win rate) × Average loss)</strong>. If this is positive, your strategy can be profitable in the long run; if negative, you will lose with it in the long run.</p>"},
  {"t": "Why is this more important than the win rate alone?", "b": "<p>A <strong style=\"color:#FF3D5A\">40% win rate can be profitable</strong> if the winning trades are on average much bigger than the losers — and a 70% win rate can be unprofitable if the rare losing trades are disproportionately large.</p>"},
  {"t": "How do you use it in practice?", "b": "<p>It is worth calculating your own expectancy <strong style=\"color:#FF3D5A\">regularly, across many trades</strong>, based on your trading journal — this gives objective feedback on whether your strategy really works, instead of relying on subjective feeling.</p>"}],
 "qs": [
  {"q": "What is expectancy?", "o": ["The simple size of the highest possible daily profit", "The average, expected profit or loss per trade", "The percentage of winning trades on its own", "The biggest single profit a strategy has ever achieved"], "e": "For a strategy, expectancy shows the average expected profit or loss per trade."},
  {"q": "Why can a strategy with a low win rate still be profitable?", "o": ["Because the win rate never affects the final result", "Because the broker guarantees profit even with a low win rate", "If the average winning trade is much bigger than the average losing trade", "It can't, a low win rate always leads to losses"], "e": "If the average size of winning trades is much bigger than that of losing trades, it can be profitable even with a low win rate."},
  {"q": "Which two pieces of data does calculating expectancy require?", "o": ["Just the broker's fee schedule converted to forints", "Only the average daily volume, no other data is needed at all", "Daily volume and the spread", "The win rate and the average win/loss size"], "e": "Calculating expectancy requires the win rate and the average win/loss size."},
  {"q": "Why is this measure more important than the win rate alone?", "o": ["It combines frequency and size in a single, more complete measure", "It isn't more important, only the win rate really matters for decisions", "Because expectancy never relates to a strategy's real performance", "Because the win rate always gives a more accurate picture by itself"], "e": "Expectancy combines win frequency and win/loss size in a more complete, more informative measure."},
  {"q": "Why is it worth calculating your own expectancy from the journal?", "o": ["Because the journal never contains enough data for this calculation", "It isn't worth it, it is a needless calculation with no practical use", "Because expectancy is always the same for every strategy", "It gives an objective picture of whether the strategy is really profitable long-term"], "e": "Expectancy calculated from your own journal gives an objective picture of whether the strategy is really profitable in the long run."}]},
"68": {"t": "Position Scaling — Stepped Entry and Exit", "s": "Why you don't always have to open/close a position in one go", "cards": [
  {"t": "What is position scaling?", "b": "<p><strong style=\"color:#FF3D5A\">Position scaling</strong> means you build up (scaling in) or close down (scaling out) a position <strong style=\"color:#FF3D5A\">in several steps</strong>, not all at once with a single decision.</p>"},
  {"t": "Scaling in — gradual entry", "b": "<p>Instead of opening the whole planned position at once, you <strong style=\"color:#FF3D5A\">enter in parts</strong> — e.g. if the price moves in the expected direction and confirms the setup, you add to the position, reducing the risk of a \"single bad timing\".</p>"},
  {"t": "Scaling out — gradual exit", "b": "<p><strong style=\"color:#FF3D5A\">Partially closing</strong> the position when in profit (e.g. closing half at a target price and letting the other half run) lets you realise profit while still taking part in a possible further move.</p>"},
  {"t": "Why isn't this technique for everyone?", "b": "<p>Scaling requires <strong style=\"color:#FF3D5A\">more complex risk management and tracking</strong> than a simple position opened/closed in one go — beginners are better off mastering the simpler, single-step approach first.</p>"}],
 "qs": [
  {"q": "What is the essence of position scaling?", "o": ["Always opening the whole position at once, in a single step", "Automatically raising leverage every day", "Building up or reducing the position step by step, in several parts", "Opening the position at full size in one single step"], "e": "Position scaling means building up or reducing a position step by step, in several parts."},
  {"q": "Why is scaling in (gradual entry) useful?", "o": ["It can reduce the risk of the average entry price when the analysis is less certain", "Because the law requires every trader to scale in", "Because scaling in always guarantees maximum profit in every case", "It isn't useful, opening the whole position at once is always best"], "e": "Scaling in can reduce the risk of the average entry price in situations where the analysis is less clear-cut."},
  {"q": "What is the advantage of scaling out (gradual exit)?", "o": ["Because the broker charges a higher commission for partial closes", "It has no advantage, closing the whole position at once is always best", "It lets us realise partial profit while letting the rest run", "Because scaling out always reduces the total profit achieved"], "e": "Scaling out lets us realise partial profit while letting the remaining part of the position run."},
  {"q": "Why is managing the stop-loss more complicated with scaling?", "o": ["Because the scaling technique rules out using a stop-loss", "It isn't more complicated, it is always exactly the same as with a single entry", "With every addition the overall position's stop must be rethought", "Because scaling always handles the stop automatically, without thinking"], "e": "When building up in steps, the overall position's stop-loss level must be rethought with every addition."},
  {"q": "Why is it worth deciding the scaling method in advance rather than on the fly?", "o": ["Because the broker automatically decides the scaling method for us", "It isn't worth it, an emotional decision on the fly is always better", "It avoids emotion-based, improvised decision-making", "Because a decision on the fly never affects the end result"], "e": "A scaling method decided in advance avoids emotion-based, improvised decision-making during the trade."}]}
});

// ---- Part 2: lessons 69–135 ----
Object.assign(window.LESSONS_EN, {
"69": {"t": "Portfolio Heat — Measuring Aggregate Risk", "s": "How 'hot' you are right now, looking at all your open positions", "cards": [
  {"t": "What is portfolio heat?", "b": "<p><strong style=\"color:#FF3D5A\">Portfolio heat</strong> measures the aggregate risk of all your simultaneously open positions — not just one by one, but together, as if every stop-loss triggered at once.</p>"},
  {"t": "Why isn't it enough to look at positions one by one?", "b": "<p>If you keep to the 1–2% risk rule within each position but <strong style=\"color:#FF3D5A\">have 5–6 positions open at once</strong>, your aggregate risk can be 10%+ if every stop triggered at once on a bad day.</p>"},
  {"t": "How can it be calculated in a simplified way?", "b": "<p>Add up <strong style=\"color:#FF3D5A\">the individual risk percentages of all open positions</strong> (what you would lose when the stop-loss is hit) — this gives the total portfolio heat, which should never exceed a predefined, safe level.</p>"},
  {"t": "Why is this especially important with correlated positions?", "b": "<p>If your open positions are <strong style=\"color:#FF3D5A\">strongly correlated</strong> with each other (see the correlation risk lesson), the real portfolio heat can be even higher, because a single market event can hit all of them at once.</p>"}],
 "qs": [
  {"q": "What is portfolio heat?", "o": ["An exact daily aggregated statement of the broker's commission", "The standalone, isolated risk of a single position", "The aggregate risk exposure of all open positions", "A symbolic indicator of the market's daily opening temperature"], "e": "Portfolio heat means the aggregate risk exposure of all simultaneously open positions."},
  {"q": "Why isn't it enough to look at positions individually?", "o": ["Because positions are never actually related to each other", "It is enough, looking individually is always completely sufficient", "Because looking individually always gives a more accurate result", "With correlated positions the aggregate risk can be higher"], "e": "With correlated positions the aggregate risk can be higher than the sum of the individual risks."},
  {"q": "What practical rule do many apply for this?", "o": ["They set an upper cap on aggregate exposure too", "Aggregate risk doesn't matter, it can be unlimited", "They never open several positions at once under any circumstances", "They always maximise the size of each position separately"], "e": "Many traders also set an upper cap on aggregate exposure, not just on individual positions."},
  {"q": "Why is this especially important during a crisis?", "o": ["It isn't, risk automatically falls during a crisis", "Because positions are always closed automatically in a crisis", "Because portfolio performance always improves during a crisis", "Correlations jump, magnifying the aggregate risk"], "e": "During a crisis correlations can jump, significantly magnifying the aggregate risk."},
  {"q": "How can high portfolio heat be reduced?", "o": ["By reducing the size of some positions or closing them", "By completely and permanently ignoring risk management", "By adding more, similarly correlated instruments to the portfolio", "By deliberately increasing position sizes further everywhere"], "e": "High portfolio heat can be reduced by reducing the size of some positions or closing them."}]},
"84": {"t": "The Concept of Risk of Ruin", "s": "The chance of losing your capital completely", "cards": [
  {"t": "What is risk of ruin?", "b": "<p><strong style=\"color:#FF3D5A\">Risk of ruin</strong> is the mathematical probability that with a given trading strategy, at a given level of risk-taking, you will lose your trading capital completely in the long run.</p>"},
  {"t": "What influences this probability most?", "b": "<p>Risk of ruin depends mainly on the <strong style=\"color:#FF3D5A\">amount of risk taken per trade and the strategy's expected value (expectancy)</strong> — the bigger the stake size with a negative or low-expectancy strategy, the higher the risk.</p>"},
  {"t": "Why is the difference between 1% and 10% risk dramatic?", "b": "<p>What at first seems a small difference (1% vs 5–10% risk per trade) <strong style=\"color:#FF3D5A\">increases the probability of losing all your capital exponentially</strong> in a longer, worse streak — one of the most important reasons for low risk-taking.</p>"},
  {"t": "Why must this be taken seriously even with a good strategy?", "b": "<p>Even with a <strong style=\"color:#FF3D5A\">statistically positive-expectancy strategy</strong> long losing streaks can occur — overly aggressive stake sizing can let an otherwise good strategy ruin the trader during a bad streak.</p>"}],
 "qs": [
  {"q": "What is risk of ruin?", "o": ["The highest leverage offered by the broker", "The probability of losing all your capital with a strategy", "The average daily loss", "The maximum allowed number of stakes per day"], "e": "Risk of ruin is the probability of losing all your capital with a strategy in the long run."},
  {"q": "What influences it most?", "o": ["The market's opening hours", "The amount of risk taken and the strategy's expected value", "Only the daily price change", "Only the broker's name"], "e": "Risk of ruin depends mainly on the amount of risk taken and the strategy's expectancy."},
  {"q": "Why is the difference between 1% and 10% risk dramatic?", "o": ["It is only a theoretical difference", "There is no difference, the effect is linear", "The probability of losing capital grows exponentially", "A higher stake always reduces risk"], "e": "Higher risk-taking increases the probability of losing all capital exponentially."},
  {"q": "Why does this matter even with a good strategy?", "o": ["Long losing streaks can occur even with a good strategy", "It doesn't, a good strategy has no risk", "Because good strategies never lose", "Because it is only relevant to bad strategies"], "e": "Even a good strategy can have long losing streaks, which an overly aggressive stake can make catastrophic."},
  {"q": "What reduces risk of ruin most effectively?", "o": ["Maximum stake size on every trade", "Opening several positions at once", "Ignoring risk management", "Low, disciplined risk-taking"], "e": "Low, disciplined risk-taking per trade is the most effective way to reduce risk of ruin."}]},
"85": {"t": "Hedging Basics in Day Trading", "s": "When you reduce risk with an opposite position", "cards": [
  {"t": "What is hedging?", "b": "<p><strong style=\"color:#FF3D5A\">Hedging</strong> means reducing the risk of an existing position with ANOTHER, opposite or correlated position — the goal is not maximising profit but moderating risk.</p>"},
  {"t": "A simple day trading example", "b": "<p>If you have a Long position in a tech stock and worry about a short-term market drop, <strong style=\"color:#FF3D5A\">you can open a smaller Short position on a tech index</strong> — this partly offsets your risk if the sector falls.</p>"},
  {"t": "Why isn't hedging free?", "b": "<p>Hedging <strong style=\"color:#FF3D5A\">also reduces potential profit</strong>, not just loss — if your original position performs well, the hedge position's loss \"takes away\" from that profit.</p>"},
  {"t": "Why isn't this a primary tool for most day traders?", "b": "<p>Because of day trading's short timeframe, most traders would rather <strong style=\"color:#FF3D5A\">simply close their position</strong> if worried than maintain a complex, two-position hedging structure — hedging is more widespread in longer-term or institutional trading.</p>"}],
 "qs": [
  {"q": "What is the basic principle of hedging?", "o": ["Doubling the existing position's size for a bigger return", "Opening an opposite position to reduce existing risk", "Growing the position for a bigger payoff", "Deliberately and significantly increasing risk in the hope of a bigger profit"], "e": "Hedging means opening an opposite position to reduce the risk of the existing exposure."},
  {"q": "Why does hedging also reduce the potential for net profit?", "o": ["It doesn't, it always leaves the possible profit unchanged", "Because hedging only increases loss, it doesn't touch profit", "The opposite position limits profit as well as loss", "Because hedging always automatically doubles the profit"], "e": "Hedging limits both possible loss and possible profit at the same time, because it offsets the move."},
  {"q": "Why is hedging more complicated in day trading than in the long term?", "o": ["Because day trading rules out any use of hedging", "It isn't more complicated, it is exactly as simple in both cases", "Because of the short timeframe there is less time to set the hedge precisely", "Because hedging is a tool only available to long-term investors"], "e": "Because of day trading's short timeframe, there is less time to set up the hedge position precisely and thoughtfully."},
  {"q": "What simple form of hedging can a day trader use?", "o": ["Deliberately and significantly increasing stake size in the same direction", "Exclusively complex, many-legged options strategies", "Always exclusively closing the whole position immediately and completely", "A smaller position opened on a correlated but opposite-direction instrument"], "e": "A simpler form can be a smaller, offsetting position opened on a correlated but opposite-direction instrument."},
  {"q": "Why doesn't hedging replace proper position sizing?", "o": ["Hedging adds extra complexity and cost, it doesn't solve every risk", "It does, hedging always removes the need for position sizing", "Because hedging automatically guarantees zero risk in every case", "Because position sizing is never relevant if the position is hedged"], "e": "Hedging adds extra complexity and cost (e.g. spread) to trading and doesn't solve every risk by itself."}]},
"95": {"t": "Handling Black Swan Events", "s": "When something completely unexpected and extreme happens", "cards": [
  {"t": "What is a Black Swan event?", "b": "<p>A <strong style=\"color:#FF3D5A\">Black Swan</strong> is an extremely rare, almost unpredictable event with extreme impact — e.g. an unexpected global crisis, a never-before-seen market crash.</p>"},
  {"t": "Why can't you \"prepare\" for these in the traditional sense?", "b": "<p>Since Black Swan events are by definition <strong style=\"color:#FF3D5A\">unforeseeable</strong>, you can't build a concrete strategy to predict them — preparation is more about handling the CONSEQUENCES.</p>"},
  {"t": "Why are the stop-loss and risk management the only real protection?", "b": "<p>During a Black Swan event <strong style=\"color:#FF3D5A\">strict, pre-set risk management</strong> (small position size, stop-loss, low leverage) is the only thing that can actually limit your damage — no analysis predicts such events precisely.</p>"},
  {"t": "Why is excessive leverage dangerous precisely at such times?", "b": "<p>During a Black Swan event the market can move <strong style=\"color:#FF3D5A\">extremely fast and to an extreme extent</strong> — with high leverage this can easily lead to losing all capital, and in some cases even a negative balance.</p>"}],
 "qs": [
  {"q": "What is a Black Swan event?", "o": ["Regular, thorough review of the daily economic calendar", "Daily review of the risk management rules", "A frequent, well-predictable event", "An extremely rare, unpredictable event with extreme impact"], "e": "A Black Swan is an extremely rare, almost unpredictable event with extreme market impact."},
  {"q": "Why can't a strategy be built to predict them?", "o": ["Because they are only theoretical concepts", "By definition they are unforeseeable", "It can, they can be predicted precisely", "Because they never happen"], "e": "Black Swan events are by definition unforeseeable, so no strategy can be built on predicting them."},
  {"q": "What is the only real protection against them?", "o": ["No protection exists at all", "Maximum leverage", "Predicting the future precisely", "Strict risk management (small position, stop-loss)"], "e": "Strict, pre-set risk management is the only real protection, since the event itself can't be predicted."},
  {"q": "Why is high leverage dangerous at such times?", "o": ["The market can move extremely, which can lead to losing all capital", "Leverage automatically decreases at such times", "Leverage always provides protection", "Because leverage automatically drops to zero at such times"], "e": "During a Black Swan event the market can move to an extreme extent; with high leverage this can be catastrophic."},
  {"q": "What is the most important lesson about them?", "o": ["Risk management matters even if the event can't be predicted", "Black Swans never affect day traders", "You must always trade with maximum leverage", "Risk management is never needed"], "e": "Strict risk management is essential even if the specific event can't be foreseen."}]},
"96": {"t": "Leverage Levels by Asset Class", "s": "Why a forex pair and a stock get different maximum leverage", "cards": [
  {"t": "Why do maximum leverage levels differ by instrument?", "b": "<p>Regulators and brokers set the maximum allowed leverage <strong style=\"color:#FF3D5A\">based on historical volatility</strong> — a more stable, less volatile instrument (e.g. a major currency pair) can get higher leverage than a more volatile one (e.g. a cryptocurrency).</p>"},
  {"t": "Forex typically has higher leverage", "b": "<p><strong style=\"color:#FF3D5A\">Major currency pairs</strong> (e.g. EUR/USD), because of their relatively low daily volatility, have traditionally received higher leverage in many jurisdictions than other asset classes.</p>"},
  {"t": "Cryptocurrencies typically have lower allowed leverage (on regulated platforms)", "b": "<p>Because of cryptocurrencies' <strong style=\"color:#FF3D5A\">higher native volatility</strong>, many regulated platforms allow lower maximum leverage on them than on traditional currency pairs.</p>"},
  {"t": "Why is it important to consider this in your own risk management?", "b": "<p>Just because a platform <strong style=\"color:#FF3D5A\">allows high leverage</strong> doesn't mean you have to use it — decide on your actual leverage based on your own risk tolerance, not on the platform's maximum allowance.</p>"}],
 "qs": [
  {"q": "Why can maximum leverage differ by asset class?", "o": ["It can't, exactly the same maximum applies to every instrument", "Because the broker sets it randomly and arbitrarily everywhere", "Regulators set the limit based on the instrument's volatility", "Because leverage limits only exist in the forex market at all"], "e": "Regulators often set the maximum allowed leverage based on the typical volatility of the given instrument."},
  {"q": "Why can forex typically get higher leverage than stocks?", "o": ["Because forex always counts as a completely risk-free asset class", "Because share prices are frozen and never fluctuate", "Forex pairs typically move with lower daily volatility", "Because the law requires brokers to do this equally in every jurisdiction"], "e": "Forex pairs typically move with lower daily volatility than many stocks, which can allow higher leverage."},
  {"q": "Why is high leverage risky on a volatile instrument?", "o": ["Because volatility never relates to the risk of leverage", "It isn't risky, it is always safe regardless of volatility", "Because high leverage always reduces the actual risk", "A small swing in a volatile instrument can wipe out much of the margin"], "e": "With high leverage, a small move in a volatile instrument can cause a disproportionately large loss relative to the capital invested."},
  {"q": "Why is it worth staying below the regulated maximum in practice?", "o": ["It isn't, you must always use the maximum allowed leverage", "Because regulators always set too low a limit in every case", "Because maximum leverage always guarantees profit", "The regulated maximum doesn't mean it is always a smart choice"], "e": "The regulated maximum is just an upper cap; using it fully isn't always a smart decision."},
  {"q": "Why is it important to check your own broker's leverage rules?", "o": ["Different rules can apply by asset class and jurisdiction", "It does not matter, every broker applies exactly the same rules", "Because the broker always automatically applies the lowest leverage", "Because leverage never affects the actual risk in any case"], "e": "Leverage rules can differ significantly by asset class and by jurisdiction, so it is worth checking them."}]},
"101": {"t": "Reward-to-Risk in Practice: A Live Example", "s": "Let's work through a real situation step by step", "cards": [
  {"t": "Setting up the situation", "b": "<p>Suppose a stock is at $50, there is a nearby support at $48 (you put the stop-loss there), and a previous resistance at $56 (you target the take-profit there). <strong style=\"color:#FF3D5A\">Let's calculate whether this trade is worth it.</strong></p>"},
  {"t": "Calculating risk and reward", "b": "<p>Risk per unit: $50 − $48 = <strong style=\"color:#FF3D5A\">$2</strong>. Reward per unit: $56 − $50 = <strong style=\"color:#FF3D5A\">$6</strong>. Risk/Reward ratio: $6 ÷ $2 = <strong style=\"color:#FF3D5A\">1:3</strong> — an excellent ratio.</p>"},
  {"t": "Adding the position size", "b": "<p>If your account is $10,000 and you follow the 1% rule, <strong style=\"color:#FF3D5A\">you can risk at most $100</strong> on this trade. Since the risk per unit is $2, that means $100 ÷ $2 = <strong style=\"color:#FF3D5A\">50 units</strong>.</p>"},
  {"t": "The big picture", "b": "<p>With 50 units: if the stop-loss triggers, <strong style=\"color:#FF3D5A\">you lose $100 (1% of capital)</strong>; if the take-profit is hit, <strong style=\"color:#FF3D5A\">you gain $300 (3% of capital)</strong> — this is the kind of mathematically well-founded decision worth thinking through before every trade.</p>"}],
 "qs": [
  {"q": "What is the risk per unit in the example ($50 entry, $46 stop)?", "o": ["$10", "$2", "$5", "$4"], "e": "Risk per unit is the difference between the entry price and the stop: $50 − $46 = $4."},
  {"q": "What is the reward per unit in the example ($50 entry, $56 target)?", "o": ["$12", "$3", "$7", "$6"], "e": "Reward per unit is the difference between the target and the entry price: $56 − $50 = $6."},
  {"q": "What is the Risk/Reward ratio in this specific example?", "o": ["1:1.5", "1:4", "1:8", "1:1"], "e": "The Risk/Reward ratio: $6 (reward) ÷ $4 (risk) = 1:1.5."},
  {"q": "Why is practising with concrete numbers important?", "o": ["Concrete calculation helps you practise fast, real-time decisions", "Because concrete numbers always mean something different from theory", "Because only the broker can calculate this ratio precisely", "It isn't, understanding the concept in theory is enough on its own"], "e": "Practising with concrete numbers helps you rehearse fast, real-time decision-making while trading."},
  {"q": "What should you do if the ratio is below your own minimum threshold?", "o": ["It is worth avoiding the trade or adjusting the levels", "The stop-loss must be dropped completely in this case", "The position size must be increased significantly to compensate", "You must always enter, completely regardless of the ratio"], "e": "If the ratio is below your own accepted minimum, it is worth avoiding the trade or adjusting the entry/exit levels."}]},
"111": {"t": "The Guaranteed Stop-Loss", "s": "The stop type that holds the price even in extreme market conditions", "cards": [
  {"t": "What is a guaranteed stop-loss?", "b": "<p>A <strong style=\"color:#FF3D5A\">guaranteed stop-loss (GSL)</strong> is a premium service offered by some brokers — they promise the stop will fill exactly at the specified price, REGARDLESS of market gaps or extreme slippage.</p>"},
  {"t": "How is this different from a traditional stop-loss?", "b": "<p>A traditional stop-loss <strong style=\"color:#FF3D5A\">doesn't guarantee the exact price</strong> in extreme market moves (a gap, a sudden plunge) — the GSL provides protection against exactly this, for an extra fee.</p>"},
  {"t": "Why does this protection carry an extra fee?", "b": "<p>The broker <strong style=\"color:#FF3D5A\">takes on the slippage risk itself</strong> behind the guaranteed stop — so this service typically comes at a premium (a wider spread or a separate fee).</p>"},
  {"t": "When is it worth considering?", "b": "<p>A GSL can be especially useful for <strong style=\"color:#FF3D5A\">volatile instruments or trading around important news</strong>, where a traditional stop-loss's slippage risk is significantly higher than usual.</p>"}],
 "qs": [
  {"q": "What is a guaranteed stop-loss?", "o": ["A stop type that guarantees execution at the given price, even jumping a gap", "A kind of take-profit order that always guarantees the best price", "A stop that the broker can remove at any time", "A stop the broker may relocate whenever it sees fit"], "e": "A guaranteed stop-loss is a stop type that guarantees execution at the given price, even on a gapping move."},
  {"q": "Why is a guaranteed stop-loss typically more expensive?", "o": ["Because a guaranteed stop never fills, so it has no real cost", "The broker can charge an extra fee for providing the guarantee", "Because a guaranteed stop always means lower risk for the broker", "It isn't more expensive, it always costs exactly the same as a plain stop"], "e": "A guaranteed stop-loss is typically more expensive because the broker can charge an extra fee for providing the guarantee."},
  {"q": "When can a guaranteed stop be especially useful?", "o": ["Only when the market is officially closed on the given day", "In extreme volatility or around news, when there is gap risk", "Only when the position size is extremely small, not otherwise", "Never useful, it always means just a needless extra cost"], "e": "A guaranteed stop can be especially useful in extreme volatility or around important news, when there is a risk of a gapping move."},
  {"q": "How is it different from a traditional stop-loss in terms of slippage?", "o": ["The guaranteed stop eliminates slippage risk compared to the traditional one", "The guaranteed stop always carries bigger slippage risk", "No meaningful difference, both carry exactly the same slippage risk", "The traditional stop is always more accurate than the guaranteed version"], "e": "A guaranteed stop-loss eliminates slippage risk, while a traditional stop becomes a market order once triggered, exposed to slippage."},
  {"q": "Why isn't it available at every broker and on every instrument?", "o": ["Providing the guarantee means extra risk and cost for the broker", "It is available everywhere, every broker and instrument offers this service", "Because a guaranteed stop is technically impossible on any instrument", "Because the law forbids this service in most jurisdictions everywhere"], "e": "Providing the guarantee means extra risk and cost for the broker, so it isn't available on every instrument and at every broker."}]},
"112": {"t": "Beta — Measuring Market Sensitivity", "s": "How much an instrument moves relative to the market as a whole", "cards": [
  {"t": "What is beta?", "b": "<p><strong style=\"color:#FF3D5A\">Beta</strong> measures how sensitive an instrument's price is to the movement of the whole market (e.g. a major index) — a beta of 1.0 means the instrument moves with the market on average.</p>"},
  {"t": "What does a high beta (>1) mean?", "b": "<p>A <strong style=\"color:#FF3D5A\">beta above 1</strong> means the instrument moves MORE than the market — if the market rises 1%, an instrument with a beta of 2 may move 2% on average.</p>"},
  {"t": "What does a low beta (<1) mean?", "b": "<p>A <strong style=\"color:#FF3D5A\">beta below 1</strong> means the instrument moves LESS than the market — it is less sensitive to the movement of the market as a whole.</p>"},
  {"t": "Why is this relevant for day traders?", "b": "<p>High-beta instruments offer <strong style=\"color:#FF3D5A\">greater daily movement potential</strong> (more opportunity, but also more risk), while low-beta instruments are more stable but give fewer short-term opportunities.</p>"}],
 "qs": [
  {"q": "What does the beta measure?", "o": ["An instrument's dividend yield", "An instrument's price sensitivity to the movement of the whole market", "The instrument's daily price range", "Daily trading volume"], "e": "Beta measures an instrument's price sensitivity to the movement of the whole market (e.g. an index)."},
  {"q": "What does a beta greater than 1 mean?", "o": ["The instrument is always less volatile than the market as a whole", "The instrument never moves together with the market in any case", "The instrument is more volatile than the market as a whole", "The instrument moves exactly like the market, one to one"], "e": "A beta greater than 1 means the instrument is more volatile and moves to a greater extent than the market as a whole."},
  {"q": "What does a beta less than 1 mean?", "o": ["The instrument is less volatile than the market as a whole", "The instrument never moves, staying at a completely fixed price", "The instrument is always more volatile than the market, without exception", "The instrument always moves in the opposite direction to the market"], "e": "A beta less than 1 means the instrument is less volatile and moves to a smaller extent than the market as a whole."},
  {"q": "Why is knowing beta useful for position sizing?", "o": ["Because beta is used solely to determine the broker's commission", "It does not matter, beta never affects sizing in any case", "Because beta always automatically guarantees equal risk", "It helps balance real risk between instruments of different volatility"], "e": "Knowing beta helps balance real risk exposure between instruments of different volatility."},
  {"q": "Why isn't beta a perfect or fixed measure?", "o": ["It is perfect and fixed, it never changes under any circumstances", "Because beta always updates instantly, in real time, every minute", "Because beta is only a theoretical concept, it can never be calculated in practice", "It is based on historical data, which can change over time, not guaranteed for the future"], "e": "Beta is an estimate based on historical data, which can change over time and is not a guaranteed measure of future behaviour."}]},
"123": {"t": "The Concept of Stop-Loss Hunting", "s": "When others target exactly the level of your stop", "cards": [
  {"t": "What is stop-loss hunting?", "b": "<p><strong style=\"color:#FF3D5A\">Stop-loss hunting</strong> is the phenomenon/theory that bigger market players deliberately move the price to a level where many stop-loss orders are known to be concentrated, triggering them.</p>"},
  {"t": "Why do stop-loss orders concentrate at certain levels?", "b": "<p>Many traders put their stop at <strong style=\"color:#FF3D5A\">the same \"round\" or technically obvious levels</strong> (e.g. just below a clearly visible support) — this creates a predictable concentration.</p>"},
  {"t": "Why is this phenomenon disputed?", "b": "<p>Although many traders believe stop-loss hunting exists, <strong style=\"color:#FF3D5A\">it is hard to prove objectively</strong> that a given move was a deliberate \"hunt\" rather than just the result of the market's normal volatility.</p>"},
  {"t": "How can you protect yourself, whether or not you believe in it?", "b": "<p>Whether or not the phenomenon exists, the defence is the same: <strong style=\"color:#FF3D5A\">don't put your stop at the obvious, \"round\" level</strong> — place it a little further away, at a less obvious but still technically justified point.</p>"}],
 "qs": [
  {"q": "What is stop-loss hunting?", "o": ["The phenomenon that stops never actually trigger", "A kind of order type that always guarantees execution", "The method for calculating the broker's aggregated daily commission", "The theory that big players move the price to levels where many stops are concentrated"], "e": "According to the stop-loss hunting theory, big players may move the price to the level of concentrated stops."},
  {"q": "Why do stops concentrate at certain levels?", "o": ["Because only one correct stop level exists for every instrument", "Randomly, there is never any logic behind it", "Many traders put their stop at the same obvious levels", "Because the broker forces every trader to do so"], "e": "Many traders put their stop at similar, technically obvious levels, creating a concentration."},
  {"q": "Why is this phenomenon disputed?", "o": ["Because it never happens in reality, it is just a theoretical concept", "Because it is only a theoretical concept nobody talks about anywhere", "It is hard to prove whether a move was a deliberate hunt", "It isn't disputed, everyone fully agrees that it exists"], "e": "It is hard to prove objectively whether a given move was a deliberate stop hunt."},
  {"q": "How can you protect yourself against it, whether or not you believe in it?", "o": ["By never using a stop-loss on any position at all", "By completely and permanently rejecting the concept of the stop-loss", "By placing the stop not at the obvious level but a little further away", "By always putting the stop at the highest possible level"], "e": "The defence is placing the stop strategically, not at the obvious level but a little further away."},
  {"q": "Which levels are worth avoiding under this logic?", "o": ["Overly obvious, round levels used by many", "Every level must be avoided equally, without exception", "It doesn't matter, it makes no difference exactly where the stop goes", "Technically justified but hidden, less obvious levels"], "e": "It is worth avoiding overly obvious, round levels that many other traders also use."}]},
"124": {"t": "Consistency vs the 'Home Run' Mentality", "s": "Why many small wins are better than one huge, rare hit", "cards": [
  {"t": "What is the \"home run\" mentality?", "b": "<p>The <strong style=\"color:#FF3D5A\">\"home run\" mentality</strong> is when a trader chases a single, huge, life-changing win — with big stakes, waiting for rare, extreme-risk opportunities.</p>"},
  {"t": "Why is this approach attractive yet dangerous?", "b": "<p>Although a \"home run\" trade is an <strong style=\"color:#FF3D5A\">exciting and appealing idea</strong>, the big stake size and risk it requires are statistically far more likely to lead to losing your capital than to one big win.</p>"},
  {"t": "Why is consistency better in the long run?", "b": "<p><strong style=\"color:#FF3D5A\">Consistent, small but regular gains</strong> — paired with good risk management — build capital much more reliably in the long run, thanks to compounding, than rare, high-risk \"shots\".</p>"},
  {"t": "What is the psychological appeal of the home run mentality?", "b": "<p>The desire for a quick, big win often comes from <strong style=\"color:#FF3D5A\">impatience and unrealistic expectations</strong> — real, sustainable trading success is typically a slow, gradual process, not a single lucky moment.</p>"}],
 "qs": [
  {"q": "What is the 'home run' mentality?", "o": ["Chasing a single huge, life-changing win with big risk", "Strictly and consistently following risk management in every situation", "The official, established name of the daily loss limit in the literature", "Striving for many small, consistent gains every single day"], "e": "The 'home run' mentality is when a trader chases a single, huge win, with big stakes and extreme risk."},
  {"q": "Why is the home run mentality statistically dangerous?", "o": ["Because it automatically reduces risk every single time", "It isn't dangerous, it is always the most effective strategy", "Because it guarantees success every time, without exception", "The big stake size and risk needed are far more likely to lead to losing capital"], "e": "The big stake size and risk the home run mentality requires are far more likely to lead to losing your capital."},
  {"q": "Why is the consistent approach better in the long run?", "o": ["Because the home run mentality always brings faster, risk-free results", "It isn't better, it always brings slower and worse results", "Because consistency never leads to real profit under any circumstances", "Small, regular gains build capital more reliably through compounding"], "e": "Consistent, small but regular gains paired with good risk management build capital more reliably in the long run."},
  {"q": "What does the psychological appeal of the home run mentality often stem from?", "o": ["Always from objective, data-based analysis after careful consideration", "Impatience and unrealistic expectations", "A thorough, in-depth knowledge of risk management in every case", "Always precisely calculating statistical probabilities"], "e": "The desire for a quick, big win often comes from impatience and unrealistic expectations, not rational analysis."},
  {"q": "What characterises real, sustainable trading success?", "o": ["A slow, gradual process with consistent risk management", "A single lucky moment with a big win that solves everything forever", "Ignoring risk management completely in every trading decision", "Always instant, quick enrichment in every single case"], "e": "Real, sustainable trading success is typically the result of a slow, gradual process, not a single lucky moment."}]},
"134": {"t": "The Concept of Value at Risk (VaR)", "s": "A number that estimates your possible loss", "cards": [
  {"t": "What is Value at Risk (VaR)?", "b": "<p><strong style=\"color:#FF3D5A\">Value at Risk (VaR)</strong> is a statistical estimate of HOW LARGE the maximum expected loss on a portfolio is over a given time horizon, at a given confidence level (e.g. 95%).</p>"},
  {"t": "A simple example of interpreting VaR", "b": "<p>If your daily VaR (at 95% confidence) is $500, it means: <strong style=\"color:#FF3D5A\">with 95% probability your daily loss won't exceed $500</strong> — but in the remaining 5% an even bigger loss can occur.</p>"},
  {"t": "Why does the remaining probability (the \"tail\") matter?", "b": "<p>VaR <strong style=\"color:#FF3D5A\">doesn't tell you HOW MUCH bigger</strong> the loss can be in the rare case it exceeds the estimated level — this is \"tail risk\", which VaR alone doesn't cover.</p>"},
  {"t": "Why is this concept still useful as a day trader?", "b": "<p>Even if you don't calculate VaR formally every day, the <strong style=\"color:#FF3D5A\">mindset</strong> behind it — \"what loss should I realistically expect, and what if something even worse happens?\" — is a useful way of thinking about risk management.</p>"}],
 "qs": [
  {"q": "What is Value at Risk (VaR)?", "o": ["The name for average daily profit", "A statistical estimate of the maximum expected loss", "The broker's minimum stake size", "A regulator-set cap on how many trades you may place daily"], "e": "VaR is a statistical estimate of how large the maximum expected loss is at a given confidence level."},
  {"q": "What does a $500 daily VaR at 95% mean?", "o": ["With 95% probability the loss won't exceed $500", "You are guaranteed to lose $500", "You always make a $500 profit", "The broker pays you $500"], "e": "A $500 VaR means that with 95% probability the daily loss won't exceed this amount."},
  {"q": "What does VaR alone not cover?", "o": ["The even bigger loss that occurs in the rare case", "The confidence level", "The probability of the loss", "The average daily profit"], "e": "VaR doesn't tell you how much bigger the loss can be in the rare case it exceeds the estimated level."},
  {"q": "What is tail risk?", "o": ["The number of daily trades", "The most common, expected result", "The fixed distance between the stop-loss and the entry price", "The bigger-than-VaR loss occurring in a rare, extreme case"], "e": "Tail risk is the risk of a loss even bigger than VaR occurring in a rare, extreme case."},
  {"q": "Why is the thinking behind VaR useful even without a formal calculation?", "o": ["Because it is only useful for institutions", "It has no use at all", "Because it guarantees the exact future", "It helps think through the expected loss and worse scenarios"], "e": "The mindset behind VaR is useful for thinking through the expected loss and worse scenarios, even without a formal calculation."}]},
"135": {"t": "Emergency Plan — If the Platform Goes Down", "s": "What to do if you are in an open position and the technology lets you down", "cards": [
  {"t": "Why make a separate plan for this?", "b": "<p>Technical problems — <strong style=\"color:#FF3D5A\">internet outage, platform crash, power cut</strong> — can happen exactly when you least want them, with an open position in hand.</p>"},
  {"t": "Why does an always-active stop-loss help?", "b": "<p>If your stop-loss order is <strong style=\"color:#FF3D5A\">already recorded on the broker's server</strong> (not just \"watched\" manually on your own screen), it triggers even if your internet connection drops.</p>"},
  {"t": "Why is it worth knowing how to reach the broker's support?", "b": "<p>If the main platform freezes, it helps to know <strong style=\"color:#FF3D5A\">how to reach the broker quickly by phone or another channel</strong>, so you can have a position closed manually if needed.</p>"},
  {"t": "Why not keep all your capital in a single risky position, partly because of this risk too?", "b": "<p>The <strong style=\"color:#FF3D5A\">risk of a technical emergency</strong> is one more argument for never putting all your capital into a single high-risk, leveraged position — the emergency plan and risk management go hand in hand.</p>"}],
 "qs": [
  {"q": "Why is it important to make an emergency plan for technical problems?", "o": ["Because the law requires it of every trader, without exception", "It isn't, such things never happen on any platform", "Because the broker always automatically solves these problems for us", "An internet outage can happen exactly when you are in an open position"], "e": "Technical problems can happen exactly when you least want them, with an open position in hand."},
  {"q": "Why does a server-side stop-loss help in an emergency?", "o": ["Because this feature is only available at certain brokers, never elsewhere", "It doesn't help, it is just as risky as manual monitoring in every case", "It triggers even if your internet connection drops", "Because a server-side stop is always more expensive than other solutions"], "e": "A stop-loss order recorded on the broker's server can trigger even if your own internet connection drops."},
  {"q": "Why is it worth knowing the broker's alternative contact options?", "o": ["Because the broker requires daily contact with every client", "Because it is the only way to register an account in the system", "It does not matter, it will never be needed under any circumstances", "So you can reach them even if the platform freezes, to request a manual close"], "e": "If the main platform freezes, it helps to know how to reach the broker quickly to handle a position manually."},
  {"q": "How does the emergency plan relate to risk management?", "o": ["There is no relationship between them, they are two completely separate concepts", "The risk of a technical emergency also warns you never to put everything in one position", "Only a theoretical relationship, not relevant at all in practice", "The emergency plan replaces risk management, making it unnecessary"], "e": "The risk of a technical emergency is a further argument for never putting all your capital into a single position."},
  {"q": "What is the most effective defence if the platform freezes during an open position?", "o": ["A pre-set, server-side stop-loss and a known alternative contact", "Nothing can be done, you just have to wait idly for it to resolve", "Immediately opening a new account at another broker, the only solution", "The position always closes automatically by itself, nothing needs doing"], "e": "The best defence is a pre-set, server-side stop-loss, supplemented by knowing the broker's alternative contact options."}]}
});

